import warnings
from django import forms
from django.forms.widgets import MediaOrderConflictWarning


class ColorPicker(forms.Widget):
    class Media:
        js = ['color-picker.js']


class SimpleTextWidget(forms.Widget):
    class Media:
        js = ['text-editor.js']


class FancyTextWidget(forms.Widget):
    class Media:
        js = ['text-editor.js', 'text-editor-extras.js', 'color-picker.js']


class MyForm(forms.Form):
    background_color = forms.CharField(widget=ColorPicker())
    intro = forms.CharField(widget=SimpleTextWidget())
    body = forms.CharField(widget=FancyTextWidget())


def test_merge_does_not_warn_and_preserves_dependency_order():
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        media = MyForm().media
        js = media._js

    conflict_warnings = [
        w for w in caught if issubclass(w.category, MediaOrderConflictWarning)
    ]
    assert conflict_warnings == [], (
        "Unexpected MediaOrderConflictWarning(s): %r" %
        [str(w.message) for w in conflict_warnings]
    )

    assert js == ['text-editor.js', 'text-editor-extras.js', 'color-picker.js'], js
